import subprocess, os, sys
BASE='/app'; DAT=BASE+'/data'; SRC=BASE+'/src'
def r_acc(i,n,b): return i.encode()+n.encode().ljust(20,b' ')+b.zfill(10).encode()
def r_book(i,t,o): return i.encode()+t.encode().ljust(20,b' ')+o.encode()
def r_trans(bk,a,s,bu): return bk.encode()+a.zfill(10).encode()+s.encode()+bu.encode()
STD_ACC=[r_acc('U001','John Doe','1180'), r_acc('U002','Jane Smith','1800'), r_acc('U003','Bob Wilson','1520')]
STD_BOOK=[r_book('B001','Python Basics','U002'), r_book('B002','COBOL Guide','U002'), r_book('B003','Java Tutorial','U002')]
STD_TRANS=[r_trans('B003','20','U003','U001'), r_trans('B003','50','U001','U002'), r_trans('B001','150','U001','U002')]
SCEN={
 'orig_fail':dict(acc=STD_ACC,book=STD_BOOK,trans=STD_TRANS,inp=('U001','U002','B007','200')),
 'neg':dict(acc=STD_ACC,book=STD_BOOK,trans=STD_TRANS,inp=('U001','U002','B001','0000005000')),
 'ovf':dict(acc=[r_acc('U001','John Doe','9999999999'),r_acc('U002','Jane Smith','9999999999'),r_acc('U003','Bob Wilson','1520')],book=STD_BOOK,trans=STD_TRANS,inp=('U001','U002','B001','0000000005')),
 'pad':dict(acc=STD_ACC,book=STD_BOOK+[r_book('B00 ','Pad Test','U002')],trans=STD_TRANS,inp=('U001','U002','B00','')),
 'same':dict(acc=STD_ACC,book=[r_book('B001','Python Basics','U001'),r_book('B002','COBOL Guide','U002'),r_book('B003','Java Tutorial','U002')],trans=STD_TRANS,inp=('U001','U001','B001','0000000100')),
 'amtmid':dict(acc=STD_ACC,book=STD_BOOK,trans=STD_TRANS,inp=('U001','U002','B001','1  0000000')),
}
def setup(s):
    open(DAT+'/ACCOUNTS.DAT','wb').write(b''.join(s['acc']))
    open(DAT+'/BOOKS.DAT','wb').write(b''.join(s['book']))
    open(DAT+'/TRANSACTIONS.DAT','wb').write(b''.join(s['trans']))
    b,se,bk,amt=s['inp']
    open(SRC+'/INPUT.DAT','wb').write((b+se+bk).encode()+amt.encode())
def run(prog,scen,tag):
    s=SCEN[scen]; setup(s)
    if prog=='cobol': r=subprocess.run(['/tmp/program_cobol'],cwd=BASE,capture_output=True)
    else: r=subprocess.run([sys.executable,'/app/program.py'],cwd=BASE,capture_output=True)
    outdir='/tmp/out/%s/%s'%(tag,scen); os.makedirs(outdir,exist_ok=True)
    for f in ('ACCOUNTS.DAT','BOOKS.DAT','TRANSACTIONS.DAT'):
        open(outdir+'/'+f,'wb').write(open(DAT+'/'+f,'rb').read())
    open(outdir+'/stdout.txt','wb').write(r.stdout)
    return r
def dump(path):
    data=open(path,'rb').read()
    for name,l,lays in (('ACCOUNTS',34,[(4,'id'),(20,'name'),(10,'bal')]),('BOOKS',28,[(4,'id'),(20,'title'),(4,'owner')]),('TRANS',22,[(4,'book'),(10,'amt'),(4,'sell'),(4,'buy')])):
        if path.endswith(name+'.DAT') or path.endswith(name):
            print(' ',name)
            p=0
            while p<len(data):
                c=data[p:p+l]; o=0; parts=[]
                for w,n in lays: parts.append(n+'='+repr(c[o:o+w])); o+=w
                print('    '+' '.join(parts)); p+=l
if __name__=='__main__':
    cmd=sys.argv[1]
    if cmd=='run':
        prog=sys.argv[2]
        for scen in SCEN: r=run(prog,scen,'cobol' if prog=='cobol' else 'py'); print('==',scen,'->',r.stdout.decode().strip())
    elif cmd=='show':
        tag=sys.argv[2]; scen=sys.argv[3]
        print('SCENARIO',scen,'['+tag+']')
        for f in ('ACCOUNTS.DAT','BOOKS.DAT','TRANSACTIONS.DAT'): dump('/tmp/out/'+tag+'/'+scen+'/'+f)
    elif cmd=='diff':
        for scen in SCEN:
            for f in ('ACCOUNTS.DAT','BOOKS.DAT','TRANSACTIONS.DAT'):
                a=open('/tmp/out/cobol/%s/%s'%(scen,f),'rb').read()
                b=open('/tmp/out/py/%s/%s'%(scen,f),'rb').read()
                if a!=b: print('MISMATCH',scen,f)
            else: pass
        print('diff done')
